INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at) VALUES (@subject_chemistry, CAST(@kp_6b9d0447a3 AS CHAR), 'ESSAY', '【2025全国卷理综化学·第26题】<br>26．（14分）碘具有重要经济价值。实验室利用沉淀法从含碘废液中回收碘，相关反应的化学方程式为：<br>（公式见原题）<br>（公式见原题）<br>实验装置如图所示。<br>实验步骤如下：<br>①向A中加入 （公式见原题） ，搅拌使其溶解。将 （公式见原题） 饱和溶液加入B中。<br>②加热至 （公式见原题） ，逐滴加入饱和 （公式见原题） 溶液。停止加热，静置，沉降。<br>③检查 （公式见原题） 是否沉淀完全。确认沉淀完全后，弃去上层清液。<br>④将B中溶液更换为浓硝酸，连接装置D。不断搅拌下，逐滴加入浓硝酸。<br>⑤待析出的 （公式见原题） 沉降后，过滤，洗涤，干燥得到产品。<br>回答下列问题：<br>（1）仪器A和C的名称分别是___________、___________。<br>（2）称取 （公式见原题） 于烧杯中，向其中加入适量蒸馏水，微热，搅拌，静置冷却，得到 （公式见原题） 饱和溶液。判断 （公式见原题） 溶液饱和的实验现象是____________________________________。<br>（3）步骤③中，确认 （公式见原题） 沉淀完全的操作及现象是：取少量清液，加入一滴淀粉溶液，________。<br>（4）步骤④中，加入浓硝酸后A中的现象是________________，D中盛放________。<br>（5）步骤⑤中，使用________（填标号）洗涤。<br>a．水b．四氟化碳c．乙醇<br>（6）若要进一步精制产品，可采取的方法是________。<div class="question-images"><img src="/images/questions/2025/chemistry/img_006.png" alt="题目配图"></div>', NULL, '（1）三颈瓶温度计<br>（2）烧杯底部有少量固体<br>（3）缓慢滴加过量氯水，无蓝色出现<br>（4）白色固体消失，析出紫黑色沉淀，产生红棕色气体，溶液呈绿色碱液<br>（5）a<br>（6）升华', '参考答案：<br>（1）三颈瓶温度计<br>（2）烧杯底部有少量固体<br>（3）缓慢滴加过量氯水，无蓝色出现<br>（4）白色固体消失，析出紫黑色沉淀，产生红棕色气体，溶液呈绿色碱液<br>（5）a<br>（6）升华', 4, '2025全国卷理综化学', @admin_id, NOW());
SET @question_id := LAST_INSERT_ID();
