INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at) VALUES (@subject_chemistry, CAST(@kp_3362fdb8ad AS CHAR), 'ESSAY', '【2025全国卷理综化学·第28题】<br>28．（15分）乙酸乙酯是一种应用广泛的有机化学品，可由乙酸和乙醇通过酯化反应制备。回答下列问题：<br>（1）乙酸、乙醇和乙酸乙酯的燃烧热分别为 （公式见原题） 、 （公式见原题） 和 （公式见原题） ，则酯化反应 （公式见原题） 的 （公式见原题） ____________ （公式见原题） 。<br>（2）酯化反应中的3种有机物的佛点从高到低的顺序为________原因是______________________________。<br>（3）在常压和 （公式见原题） 时，初始组成 （公式见原题） 、 （公式见原题） 作催化剂的条件下进行反应，得到乙醇浓度随反应时间的变化如下图所示。<br>平衡时乙酸的转化率 （公式见原题） ________ （公式见原题） ，平衡常数 （公式见原题） ________（保留2位有效数字）。已知酯化反应的速率方程为 （公式见原题） ，其中 （公式见原题） ，则 （公式见原题） _________ （公式见原题） （保留2位有效数字）。<br>（4）研究发现，难以通过改变反应温度或压强来提高乙酸乙酯平衡产率，原因是________________。若要提高乙酸乙酯的产率，可以采用的方法是________________（举1例）。<div class="question-images"><img src="/images/questions/2025/chemistry/img_009.png" alt="题目配图"></div>', NULL, '（1） （公式见原题）<br>（2） （公式见原题）<br>乙酸乙酯分子间不存在氢键，乙酸分子间的氢键比乙醇的更强<br>（3）303.9 （公式见原题）<br>（4） （公式见原题） 很小，温度对平衡影响小；液相反应，压强对平衡影响小及时移出产物', '参考答案：<br>（1） （公式见原题）<br>（2） （公式见原题）<br>乙酸乙酯分子间不存在氢键，乙酸分子间的氢键比乙醇的更强<br>（3）303.9 （公式见原题）<br>（4） （公式见原题） 很小，温度对平衡影响小；液相反应，压强对平衡影响小及时移出产物', 4, '2025全国卷理综化学', @admin_id, NOW());
